css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .figura-mini{width: 38px; height: 38px;}
.mz .banco{border: 1.5px dashed #000; border-radius: 8px; padding: 5px 10px; text-align: center; font-size: 13px; font-weight: 700; margin-bottom: 6px;}
.mz .nombrar-grid{display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px;}
.mz .nombrar-caja{border: 1.5px solid var(--bosque); border-radius: 8px; padding: 6px 8px; display: flex; flex-direction: column; align-items: center; gap: 4px;}
.mz .nombrar-linea{border-bottom: 1.5px solid var(--bosque); height: 22px; width: 100%;}
.mz .unir-grid{display: grid; grid-template-columns: 1fr 1fr; gap: 7px 40px; align-items: center;}
.mz .unir-col{display: flex; flex-direction: column; gap: 6px; align-items: center;}
.mz .unir-fig{display: flex; align-items: center; justify-content: center; min-height: 40px;}
.mz .unir-fig svg{width: 40px; height: 40px;}
.mz .unir-nom{border: 1.5px solid var(--bosque); border-radius: 8px; padding: 7px 8px; text-align: center; font-size: 13.5px; font-weight: 700; width: 100%;}
.mz .rodear-mosaico{display: grid; grid-template-columns: repeat(6, 1fr); gap: 5px;}
.mz .rodear-fig{border: 1.5px dashed #000; border-radius: 8px; padding: 3px; display: flex; align-items: center; justify-content: center; min-height: 46px;}
.mz .vf-lista{display: flex; flex-direction: column; gap: 6px;}
.mz .vf-item{display: flex; align-items: center; justify-content: space-between; gap: 10px; font-size: 13px; border-bottom: 1px dotted #999; padding-bottom: 3px;}
.mz .vf-opciones{font-family: sans-serif; font-weight: 700; font-size: 12.5px; white-space: nowrap;}
.mz .dibujar-grid{display: grid; grid-template-columns: repeat(2, 1fr); gap: 12px;}
.mz .dibujar-caja{display: flex; flex-direction: column; align-items: center; gap: 4px;}
.mz .dibujar-titulo{font-size: 12.5px; font-weight: 700; text-align: center;}
.mz .dibujar-zona{border: 1.5px solid var(--bosque); border-radius: 8px; width: 100%; height: 104px;}
